-- One lookup over both lists (bob74 and these): key -> label, mode, crowd, hide, plain (no style parts).
-- hide = open in the world: kept so an old room still loads, never offered for a new one.
StudioInteriorInfo = {}
for _, e in ipairs(StudioIpls or {}) do
    StudioInteriorInfo[e.export] = { label = e.label, mode = e.mode or 'walk', crowd = e.crowd or false, hide = e.hide or false }
end
for _, e in ipairs(StudioGameInteriors) do
    StudioInteriorInfo[e.key] = { label = e.label, mode = e.mode, crowd = e.crowd or false, hide = false, plain = true }
end

---'walk' or 'drive' for an interior key (a world place, at:..., is always walk).
function Studio.InteriorMode(key)
    local i = StudioInteriorInfo[key]
    return i and i.mode or 'walk'
end
